/// <summary>
/// Finds an environment by its id.
/// </summary>
/// <param name = "_environmentId">The environment id.</param>
/// <param name = "_forUpdate">true if the record is selected for update.</param>
/// <returns>The environment record; an empty buffer if it does not exist.</returns>
public static OLK_EnvironmentDataSetupTable find(OLK_EdsEnvironmentId _environmentId, boolean _forUpdate = false)
{
    OLK_EnvironmentDataSetupTable environment;

    if (_environmentId)
    {
        environment.selectForUpdate(_forUpdate);

        select firstonly environment
            where environment.EnvironmentId == _environmentId;
    }

    return environment;
}

/// <summary>
/// Checks whether an environment exists.
/// </summary>
/// <param name = "_environmentId">The environment id.</param>
/// <returns>true if the environment exists.</returns>
public static boolean exist(OLK_EdsEnvironmentId _environmentId)
{
    return _environmentId
        && (select firstonly RecId from OLK_EnvironmentDataSetupTable
                where OLK_EnvironmentDataSetupTable.EnvironmentId == _environmentId).RecId != 0;
}

/// <summary>
/// Finds the master environment.
/// </summary>
/// <returns>The master environment; an empty buffer if none is marked as master.</returns>
public static OLK_EnvironmentDataSetupTable findMaster()
{
    OLK_EnvironmentDataSetupTable environment;

    select firstonly environment
        where environment.MasterEnvironment == NoYes::Yes;

    return environment;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (ret && this.MasterEnvironment)
    {
        OLK_EnvironmentDataSetupTable master;

        select firstonly EnvironmentId from master
            where master.MasterEnvironment == NoYes::Yes
               && master.RecId             != this.RecId;

        if (master.EnvironmentId)
        {
            ret = checkFailed(strFmt("@OLK_EDSLabel:OnlyOneMaster", master.EnvironmentId));
        }
    }

    return ret;
}
